import{_ as e,o as i,c as s,a3 as t}from"./chunks/framework.CWpttWmj.js";const k=JSON.parse('{"title":"Pricing & rarity","description":"","frontmatter":{},"headers":[],"relativePath":"guide/pricing.md","filePath":"guide/pricing.md","lastUpdated":null}'),n={name:"guide/pricing.md"};function r(h,a,l,o,p,d){return i(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="pricing-rarity" tabindex="-1">Pricing &amp; rarity <a class="header-anchor" href="#pricing-rarity" aria-label="Permalink to &quot;Pricing &amp; rarity&quot;">​</a></h1><p>Names are priced by <strong>length</strong>, in tiers, per year. Short names cost more because there are fewer of them.</p><h2 id="how-the-price-is-calculated" tabindex="-1">How the price is calculated <a class="header-anchor" href="#how-the-price-is-calculated" aria-label="Permalink to &quot;How the price is calculated&quot;">​</a></h2><p>Two steps. A yearly rate is chosen from the name&#39;s length, then prorated across your duration:</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">usdPerYear</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(len)          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// tier lookup</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">price</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(nm, dur) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> usdPerYear</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bytes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(nm).length) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> dur </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 365</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> days</span></span></code></pre></div><p>Proration is exact and to the second — registering for 18 months costs precisely 1.5× the yearly rate. There is no rounding up to whole years and no minimum beyond 28 days.</p><p>Length is measured in <strong>bytes</strong>, not visible characters. For ordinary lowercase names those are the same thing. For a name containing multi-byte characters they are not — see <a href="/docs/guide/registering.html#what-makes-a-name-valid">Registering → what makes a name valid</a>.</p><h2 id="the-tiers" tabindex="-1">The tiers <a class="header-anchor" href="#the-tiers" aria-label="Permalink to &quot;The tiers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name length</th><th>Rate</th></tr></thead><tbody><tr><td>2 characters</td><td><code>price2</code></td></tr><tr><td>3 characters</td><td><code>price3</code></td></tr><tr><td>4 characters</td><td><code>price4</code></td></tr><tr><td>5 or more</td><td><code>price5plus</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">These are live on-chain values, not constants</p><p>All four rates are set by the contract owner through <code>setPrices</code> and can change at any time. This page deliberately does not print the current numbers — anything written here would eventually be wrong.</p><p>The app always shows the live price, fetched from the contract, before you confirm. To read them yourself, call <code>usdPerYear(len)</code> on the controller. See <a href="/docs/protocol/contracts.html">Contract addresses</a>.</p></div><p>Note that the tiers are independent values, not a curve. There is no guarantee that a 3-character name is cheaper than a 2-character one, or that 4 is cheaper than 3 — the owner sets each tier separately. Read the actual rate rather than assuming it follows from length.</p><h2 id="two-character-names-can-be-switched-off" tabindex="-1">Two-character names can be switched off <a class="header-anchor" href="#two-character-names-can-be-switched-off" aria-label="Permalink to &quot;Two-character names can be switched off&quot;">​</a></h2><p>A 2-character name is only registerable when <code>price2</code> is greater than zero:</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (len </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &amp;&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> price2 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// valid()</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(price2 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2char&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);                </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// usdPerYear()</span></span></code></pre></div><p>Setting <code>price2</code> to zero disables the entire 2-character tier. Attempting to register one then fails validation with <code>invalid</code>, and asking for its price reverts with <code>2char</code>. The app shows such names as unusable rather than as available.</p><h2 id="the-minimum-length" tabindex="-1">The minimum length <a class="header-anchor" href="#the-minimum-length" aria-label="Permalink to &quot;The minimum length&quot;">​</a></h2><p><code>minLen</code> is owner-configurable via <code>setLimits</code> and can never be set below 2. Any name shorter than it fails <code>valid()</code>, and requesting a price for one reverts with <code>short</code>.</p><p>Raising <code>minLen</code> does not affect names already registered below the new floor — they remain owned, renewable and tradeable. It only blocks new registrations.</p><h2 id="what-you-actually-pay" tabindex="-1">What you actually pay <a class="header-anchor" href="#what-you-actually-pay" aria-label="Permalink to &quot;What you actually pay&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>price(name, duration)          the contract&#39;s quote</span></span>
<span class="line"><span>  − referral discount          if a referrer is supplied and discounts are enabled</span></span>
<span class="line"><span>  = amount due</span></span>
<span class="line"><span>  + gas                        network fee, paid to validators, not to Arc Names</span></span></code></pre></div><p>Overpayment is refunded in the same transaction, so sending a buffer above the quote is safe and is exactly what the app does to survive a price change between quote and mint. See <a href="/docs/guide/registering.html#paying">Registering → paying</a>.</p><h2 id="reading-the-price-yourself" tabindex="-1">Reading the price yourself <a class="header-anchor" href="#reading-the-price-yourself" aria-label="Permalink to &quot;Reading the price yourself&quot;">​</a></h2><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> wei</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> client.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">readContract</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  address: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">CONTROLLER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  abi: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">CONTROLLER_ABI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  functionName: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;price&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  args: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;alice&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">365</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 24</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 60</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 60</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">n</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>The result is in <strong>native wei, 18 decimals</strong>, and because 1 USD of price is scaled to exactly <code>1e18</code> native wei, the returned figure is also the USD price. Format it with 18 decimals.</p><p>For the 6-decimal ERC-20 path, <code>priceUSDC(nm, dur)</code> returns the same amount divided by <code>1e12</code>. See <a href="/docs/protocol/fees.html#two-kinds-of-usdc">Fees → two kinds of USDC</a>.</p><h2 id="rarity-in-practice" tabindex="-1">Rarity in practice <a class="header-anchor" href="#rarity-in-practice" aria-label="Permalink to &quot;Rarity in practice&quot;">​</a></h2><p>Length is the only property the protocol itself prices. Everything else that makes a name desirable — a real word, a short number, a recognisable handle — is a market judgement, and shows up in <a href="/docs/guide/marketplace.html">marketplace</a> prices rather than in registration prices.</p><p>Two consequences worth knowing:</p><ul><li><strong>Registration price is a floor, not a market price.</strong> A name someone else wants can be resold for far more than it cost to register. That is what the marketplace is for.</li><li><strong>Renewal is priced the same way as registration.</strong> Holding a short name costs the short-name rate every year, indefinitely. Factor that in before registering a portfolio of them.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/docs/guide/registering.html">Registering a name</a> — the full flow.</li><li><a href="/docs/guide/renewals.html">Renewals &amp; expiry</a> — the ongoing cost.</li><li><a href="/docs/protocol/fees.html">Fees</a> — protocol fees, marketplace fees, and gas.</li></ul>`,31)])])}const g=e(n,[["render",r]]);export{k as __pageData,g as default};
